'use strict';
const NEWS=[
 {id:'n1',headline:'資料検索・要約に使えるAI機能のアップデート',date:'11月16日',body:['業務資料の検索や要約に使うAIのニュースを、この欄に表示する想定です。','この記事は画面確認用の架空記事です。実際のニュース配信には接続していません。']},
 {id:'n2',headline:'コーディング支援AIの業務活用事例',date:'11月15日',body:['コード作成や既存ツールの改善に関する外部のAIニュースを表示する想定です。','Codexで資料を探した際にも、検索結果に加えて最新のAIニュースを受け取る流れを想定しています。ここでは表示例のみを確認できます。']},
 {id:'n3',headline:'画像生成・編集ツールの新機能をチェック',date:'11月14日',body:['制作業務で使えるAI機能を知るための外部ニュース欄です。','この記事は表示用サンプルです。実際の報道や社内の決定事項ではありません。']}
];
const SECTION_INFO={ディレクター:'大会の準備・振り返り',トーナメント:'競技進行・運営',メディア:'撮影・取材・発信',カスタマー:'受付・問い合わせ対応',クリエイティブ:'バナー・制作物',ロジスティックス:'備品・搬入出',マーケティング:'告知・キャンペーン',営業:'協賛・提案',インフルエンサー:'出演・投稿連携',その他:'部署共通の資料・ツール'};
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const a=(path,text,cls='')=>`<a class="${cls}" href="#${esc(path)}">${text}</a>`;
const byId=id=>MATERIALS.find(m=>m.id===Number(id));
const business=id=>BUSINESSES.find(b=>b.id===id);
const encoded=encodeURIComponent;
let saved=new Set([2,4]),mode='link',pickOffset=0;
try{const x=JSON.parse(sessionStorage.getItem('portal-c-v1'));if(x){saved=new Set(Array.isArray(x.saved)?x.saved.filter(Number.isInteger):[]);MATERIALS.push(...(Array.isArray(x.added)?x.added:[]).filter(m=>m&&Number.isInteger(m.id)&&m.id>=1001&&typeof m.title==='string'&&SECTIONS.includes(m.section)));}}catch{}
function persist(){try{sessionStorage.setItem('portal-c-v1',JSON.stringify({saved:[...saved],added:MATERIALS.filter(m=>m.id>=1001)}));}catch{}}
function toast(t){const e=document.createElement('div');e.className='toast';e.textContent=t;$('toastWrap').append(e);setTimeout(()=>e.remove(),3500);}
function route(){const raw=location.hash.slice(1)||'/';const i=raw.indexOf('?'),path=i<0?raw:raw.slice(0,i),query=i<0?'':raw.slice(i+1);let parts;try{parts=path.split('/').filter(Boolean).map(decodeURIComponent);}catch{parts=['missing'];}return{parts,params:new URLSearchParams(query)};}
function go(path){if(location.hash==='#'+path)render();else location.hash=path;}
function crumb(parts){$('crumbs').innerHTML=parts.length?[a('/','部署・大会'),...parts.map(([n,p])=>p?a(p,esc(n)):`<span aria-current="page">${esc(n)}</span>`)].join('<span>›</span>'):'';}
function heading(t,p=''){return `<div class="page-heading"><h1>${esc(t)}</h1>${p?`<p>${esc(p)}</p>`:''}</div>`;}
function info(title,body){$('infoTitle').textContent=title;$('infoBody').innerHTML=body;if(!$('infoDialog').open)$('infoDialog').showModal();}
function dateKey(m){const p=String(m.updated).match(/(\d+)月(\d+)日/);return p?Number(p[1])*100+Number(p[2]):0;}
function sorted(list,sort='new'){return [...list].sort(sort==='title'?(x,y)=>x.title.localeCompare(y.title,'ja'):(x,y)=>dateKey(y)-dateKey(x)||y.id-x.id);}
function sourceLabel(m){if(m.url){try{const h=new URL(m.url).hostname;return h==='github.com'?'GitHub':h==='drive.google.com'?'Google Drive':h==='docs.google.com'?'Google Docs / Sheets':'公開ページ';}catch{}}return m.link||'リンク';}
function counts(list){const n=list.filter(m=>m.type==='ツール').length;return `資料 ${list.length-n} · ツール ${n}`;}
function saveButton(m){return `<button class="save-button ${saved.has(m.id)?'saved':''}" data-save="${m.id}" aria-label="${esc(m.title)}を${saved.has(m.id)?'保存済みから外す':'保存する'}" aria-pressed="${saved.has(m.id)}">${saved.has(m.id)?'★':'☆'}</button>`;}
function openButton(m){return m.hasAccess===false?`<button class="btn" data-request="${m.id}">権限を申請 ↗</button>`:`<button class="btn primary" data-external="${m.id}">開く ↗</button>`;}
function rows(list){return list.length?`<div class="resource-list">${list.map(m=>`<article class="resource-row"><span class="file-icon">${m.hasAccess===false?'限定':m.type==='ツール'?'APP':m.type==='HTML'?'HTML':m.type==='管理表'?'SHEET':'DOC'}</span><div class="resource-copy">${a('/resource/'+m.id,`${esc(m.title)}<span class="type-badge">${esc(m.type)}</span>${m.hasAccess===false?'<span class="limited">限定共有</span>':''}`,'resource-title')}<p>${esc(m.purpose||'用途の説明はまだ登録されていません。')}</p><div class="resource-tags">${a('/section/'+encoded(m.section),esc(m.section))}<span>·</span>${a('/tournament/'+encoded(m.tournament),esc(m.tournament)+' '+esc(m.round))}<span>·</span><span>${esc(sourceLabel(m))}</span>${m.tag?a('/search?q='+encoded(m.tag),'#'+esc(m.tag)):''}</div></div><div class="resource-owner">${esc(m.owner==='sha'?'自分':m.owner)}<small>${esc(m.updated)}</small></div><div class="resource-actions">${openButton(m)}${saveButton(m)}</div></article>`).join('')}</div>`:'<div class="empty">該当する資料・ツールがありません。<br>検索や絞り込みの条件を変更してください。</div>';}
// Presentation fixtures only: no material fields, registration inputs or persistence changes.
function departmentIcon(section){return `<span class="dept-icon" data-dept="${esc(section)}" aria-hidden="true">${esc(section.slice(0,1))}</span>`;}
const UI_USAGE_EXAMPLES={
  2:['対象の大会・開催回、確認したい日付','シートを開き、対象日の販売数・入場数を確認','編集する場合は、原本の権限と運用ルールを確認'],
  8:['バナーに掲載する文字、参照する素材','ツールを開き、内容を入力して出力を確認','公開前に表記と画像サイズを確認'],
  12:['対象大会、振り返りたい内容','シートを開き、項目に沿って記録・確認','共有範囲と更新先を確認してから編集'],
  13:['対象大会、確認したい参加状況','管理表を開き、対象の項目を確認','実際の入力方法は原本の説明を確認'],
  15:['対象大会、確認したい担当・ポジション','配置表を開き、担当と配置を確認','対象の開催回と原本の更新日を確認'],
  17:['対象会場、確認したい備品','一覧を開き、品目と数量を確認','原本の更新日と担当者を確認']
};
function usageBlock(m){const sample=UI_USAGE_EXAMPLES[m.id];if(!sample)return '';return `<section class="usage-section" aria-label="使い方の表示例"><div class="usage-heading"><h2>使い方</h2><span>表示例</span></div><dl class="usage-grid">${['必要な情報','操作','注意'].map((label,i)=>`<div><dt>${label}</dt><dd>${esc(sample[i])}</dd></div>`).join('')}</dl><p class="usage-note">画面確認用のサンプルです。実際の利用手順ではありません。</p></section>`;}
function groupCard(name,event=false){const list=sorted(MATERIALS.filter(m=>event?m.tournament===name:m.section===name));const path=event?'/tournament/':'/section/';const latest=list[0];return `<article class="department-card" data-dept="${event?'':esc(name)}">${a(path+encoded(name),`${event?`<span class="dept-icon">${esc(name)}</span>`:departmentIcon(name)}<h2>${esc(name)}</h2><p>${event?'この大会に関連する共有資料':esc(SECTION_INFO[name]||'共有された資料・ツール')}</p><span class="dept-counts">${counts(list)}</span>`,'dept-main')}${latest?a('/resource/'+latest.id,`<small>最新 ${esc(latest.updated)}</small><strong>${esc(latest.title)}</strong>`,'latest'):'<div class="latest"><small>まだ登録されていません</small><span>資料を登録すると表示されます。</span></div>'}</article>`;}
function picks(){const pool=[8,11,2,5,9,12].map(byId).filter(Boolean);const list=[pool[pickOffset%pool.length],pool[(pickOffset+1)%pool.length]];return list.map(m=>a('/resource/'+m.id,`<span class="tag">${esc(m.section)}</span><span>${esc(m.title)}</span><span class="arrow">→</span>`,'pick-line')).join('');}
function home(event=false){crumb([]);return `<div class="overview-heading"><div><h1>${event?'大会ごとの共有資料':'各部署の共有資料'}</h1><p>登録されている資料・ツールを、${event?'大会':'部署'}から探せます。</p></div><div class="segmented" aria-label="一覧の切り替え">${a('/','部署別',event?'':'active')}${a('/tournaments','大会別',event?'active':'')}</div></div><div class="department-grid ${event?'event-grid':''}">${(event?[...TOURNAMENTS,'共通']:SECTIONS).map(n=>groupCard(n,event)).join('')}</div><div class="below-home"><section><div class="section-header"><h2>PICK UP<small>ほかの部署の共有から</small></h2><button data-picks>別のおすすめ ↻</button></div><div id="pickLines">${picks()}</div><p class="sample-note">おすすめ表示のサンプル。自動抽出の方式は今後検討します。</p></section><section><div class="section-header"><h2>AIニュース<small>外部のAI関連情報</small></h2>${a('/news','一覧 →')}</div>${NEWS.slice(0,2).map(n=>a('/news/'+n.id,`<span>${esc(n.headline)}</span><span class="date">${n.date} · 表示例 ↗</span>`,'news-line')).join('')}</section></div>`;}
function filterOption(v,current,label=v){return `<option value="${esc(v)}" ${v===current?'selected':''}>${esc(label)}</option>`;}
function filteredList(params,scope={}){const q=params.get('q')||'',section=scope.section||params.get('section')||'',tournament=scope.tournament||params.get('tournament')||'',type=params.get('type')||'',round=scope.round||params.get('round')||'',sort=params.get('sort')||'new';let list=MATERIALS.filter(m=>(!scope.mine||m.owner==='sha')&&(!scope.saved||saved.has(m.id))&&(!scope.business||m.business===scope.business)&&(!section||m.section===section)&&(!tournament||m.tournament===tournament)&&(!type||m.type===type)&&(!round||m.round===round));const norm=s=>s.normalize('NFKC').toLocaleLowerCase('ja');if(q){const terms=norm(q).split(/\s+/).filter(Boolean);list=list.filter(m=>terms.every(t=>norm([m.title,m.purpose,m.section,m.tournament,m.round,m.tag,business(m.business)?.title||''].join(' ')).includes(t)));}const rounds=[...new Set(MATERIALS.filter(m=>!tournament||m.tournament===tournament).map(m=>m.round).filter(Boolean))];return `<form class="list-toolbar" id="filters">${scope.section?'':`<label>セクション<select name="section">${filterOption('',section,'すべて')}${SECTIONS.map(s=>filterOption(s,section)).join('')}</select></label>`}${scope.tournament?'':`<label>大会<select name="tournament">${filterOption('',tournament,'すべて')}${[...TOURNAMENTS,'共通'].map(s=>filterOption(s,tournament)).join('')}</select></label>`}<label>種類<select name="type">${filterOption('',type,'すべて')}${['資料','管理表','ツール','リンク','HTML'].map(s=>filterOption(s,type)).join('')}</select></label>${scope.round?'':`<label>開催回<select name="round">${filterOption('',round,'すべて')}${rounds.map(s=>filterOption(s,round)).join('')}</select></label>`}<label>並び順<select name="sort">${filterOption('new',sort,'更新が新しい順')}${filterOption('title',sort,'名前順')}</select></label><span class="count">${list.length}件</span></form>${rows(sorted(list,sort))}`;}
function pageList(kind,params){const title={library:'すべての資料・ツール',mine:'自分の資料',saved:'保存済み',search:'検索結果'}[kind];crumb([[title]]);return heading(title,kind==='search'?`「${params.get('q')||''}」で資料・ツールを検索しています。`:'登録されている内容から、用途を確認して開けます。')+filteredList(params,{mine:kind==='mine',saved:kind==='saved'});}
function sectionPage(s,params){crumb([['部署','/'],[s]]);const list=MATERIALS.filter(m=>m.section===s);return `<div class="scope-heading">${departmentIcon(s)}<div><h1>${esc(s)}</h1><p>${esc(SECTION_INFO[s]||'共有された資料・ツール')} · ${counts(list)}</p></div></div>${filteredList(params,{section:s})}`;}
function tournamentPage(t,params,round=''){crumb([['大会','/tournaments'],...(round?[[t,'/tournament/'+encoded(t)],[round]]:[[t]])]);const list=MATERIALS.filter(m=>m.tournament===t&&(!round||m.round===round));return heading(t+(round?' '+round:''),`登録されている大会関連の共有資料 · ${counts(list)}`)+filteredList(params,{tournament:t,round});}
function businessPage(b,params){crumb([[b.section,'/section/'+encoded(b.section)],[b.title]]);return heading(b.title,b.purpose)+filteredList(params,{business:b.id})+'<p class="business-note">すでに関連付けられている資料だけを表示しています。</p>';}
function metadata(m){return `<section class="metadata"><h2>基本情報</h2><dl class="detail-meta">${[['部署',a('/section/'+encoded(m.section),esc(m.section))],['登録者',esc(m.owner==='sha'?'自分':m.owner)],['最終更新',esc(m.updated)],['ポータル共有範囲',esc(m.share)],['リンク先',esc(sourceLabel(m))],...(m.filename?[['ファイル名',esc(m.filename)]]:[])].map(([n,v])=>`<div><dt>${n}</dt><dd>${v}</dd></div>`).join('')}</dl></section>`;}
function detail(m){const b=business(m.business);crumb([['部署','/'],[m.section,'/section/'+encoded(m.section)],[m.title]]);const related=sorted(MATERIALS.filter(x=>x.section===m.section&&x.id!==m.id)).slice(0,3);return `<div class="detail-heading"><div><div class="detail-department">${departmentIcon(m.section)}${a('/section/'+encoded(m.section),esc(m.section))}</div><h1>${esc(m.title)}</h1><div class="detail-tags"><span class="taglink">${esc(m.type)}</span>${a('/tournament/'+encoded(m.tournament),esc(m.tournament)+' '+esc(m.round))}${m.tag?a('/search?q='+encoded(m.tag),'#'+esc(m.tag)):''}</div></div><div class="detail-actions">${openButton(m)}<button class="btn" data-save="${m.id}">${saved.has(m.id)?'★ 保存済み':'☆ 保存する'}</button></div></div><div class="detail-grid"><section class="detail-copy"><h2>何に使えるか</h2><p class="purpose">${esc(m.purpose||'用途の説明はまだ登録されていません。')}</p>${usageBlock(m)}<p class="description">${m.filename?'HTMLファイル名を登録した表示例です。本体のアップロードは行っていません。':'資料やツールの本体は、リンク先にある既存の保存先を利用します。'}</p>${b?`<div class="related-business"><span>関連する業務</span>${a('/business/'+b.id,esc(b.title)+' →')}</div>`:''}<h2>${esc(m.section)}のほかの資料</h2><div class="related-list">${related.map(x=>a('/resource/'+x.id,`<span>${esc(x.title)}</span><small>${esc(x.type)} · ${esc(x.updated)}</small>`)).join('')||'<p class="sample-note">ほかの資料はまだ登録されていません。</p>'}</div></section><aside>${metadata(m)}${m.hasAccess===false?`<section class="permission-box"><h2>原本の閲覧権限が必要です</h2><p>このGitHub資料は限定公開です。ポータルから、資料の公開者にアクセスを申請する流れを確認できます。</p><button class="btn" data-request="${m.id}">Slackでアクセスをリクエスト</button></section>`:''}<p class="sample-note">サンプル資料です。実際の原本・共有設定には接続していません。</p></aside></div>`;}
function newsPage(id){const n=NEWS.find(x=>x.id===id);if(!n)return missing();crumb([['AIニュース','/news'],[n.headline]]);return heading(n.headline)+`<article class="news-article"><div class="article-meta">${n.date} · 架空記事／表示例</div>${n.body.map(s=>`<p>${esc(s)}</p>`).join('')}<div class="notice">画面確認用の記事です。実際の報道ではありません。</div></article>`;}
function connectionsNav(kind){return `<div class="connections-nav">${a('/codex','Codex連携','btn '+(kind==='codex'?'primary':''))}${a('/slack','Slack連携','btn '+(kind==='slack'?'primary':''))}</div>`;}
function codexPage(){crumb([['Codex連携']]);return heading('Codexと連携','ポータルを開かずに、資料の検索・取得・登録を行う表示例です。')+connectionsNav('codex')+`<div class="conversation"><div class="bubble user"><span class="label">あなた</span>Voucherの資料を探して</div><div class="bubble"><span class="label">Codex · 検索結果の表示例</span>${a('/resource/1','Voucher関連資料')}（カスタマー · JOPT #03）が見つかりました。<br>用途：来場者向けVoucherの発行条件と利用ルールの確認。</div><div class="bubble"><span class="label">あわせて届く最新AIニュース · 表示例</span>${a('/news/n1',esc(NEWS[0].headline))}<br><small>利用時に、資料の検索結果と最新ニュースを一緒に受け取る想定です。</small></div><div class="bubble user"><span class="label">あなた</span>この成果物を業務ポータルに登録して</div><div class="bubble"><span class="label">Codex · 登録の表示例</span>投稿ルールを確認し、不足している情報を確認します。登録内容の確認後に共有へ進みます。<br><button class="btn" data-register style="margin-top:10px">登録内容の確認を体験する →</button></div></div><div class="notice">MCP接続・ニュース配信・実際の登録は未接続です。</div>`;}
function slackSteps(m){return `<div class="step"><strong>① 社員がポータルで資料を発見</strong>${a('/resource/'+m.id,esc(m.title))}<small>保存先：GitHub（限定公開）</small></div><div class="step"><strong>② Slackで公開者へ通知</strong>サンプルユーザーが「${esc(m.title)}」へのアクセスを希望しています。<small>通知先：${esc(m.owner)}（この資料の登録者／公開者を想定）</small></div><div class="step"><strong>③ 公開者が確認・承認</strong>申請者と利用目的を確認し、承認後にGitHubへの招待へ進む想定です。</div>`;}
function slackPage(){crumb([['Slack連携']]);return heading('Slackでアクセスを申請','GitHubに置かれた限定公開の資料を、見つける・申請するための入口です。')+connectionsNav('slack')+`<div class="conversation">${slackSteps(byId(7))}<button class="btn primary" data-request="7">アクセス申請を体験する →</button></div><div class="notice">Slack通知・承認・GitHub招待は表示例です。実際には実行されません。ポータルに掲載されても、GitHub側の閲覧権限は別に必要です。</div>`;}
function showSlack(m){if(!m||m.hasAccess!==false)return;info('アクセス申請のプレビュー',`<p class="lead">資料：${esc(m.title)}</p><div class="notice">外部送信は行いません。以下は公開者へ届く通知の表示例です。</div>${slackSteps(m)}<div class="modal-actions"><button class="btn" data-close>閉じる</button><button class="btn primary" data-request-demo="${m.id}">申請後の表示を見る</button></div>`);}
function openExternal(m){if(!m)return;if(m.hasAccess===false){showSlack(m);return;}if(m.url&&/^https?:\/\//i.test(m.url)){info('登録したリンクを開く',`<p class="lead">${esc(m.title)}</p><p style="overflow-wrap:anywhere">${esc(m.url)}</p><a class="btn primary" href="${esc(m.url)}" target="_blank" rel="noopener noreferrer">リンク先へ進む ↗</a><p class="sample-note">このタブで登録したリンクです。外部サイトが開きます。</p>`);return;}info('リンク先の表示例',`<p class="lead">${esc(m.title)}</p><div class="notice">${m.filename?'HTMLファイル名だけを確認したサンプルです。本体はアップロードしていません。':'サンプル資料のため、原本のリンクは未接続です。正式版では、この操作から既存の保存先を開きます。'}</div><p class="sample-note">この原型では、ツール本体の操作画面を新しく作成していません。</p>`);}
function missing(){crumb([['ページが見つかりません']]);return heading('ページが見つかりません')+a('/','部署一覧に戻る →','btn');}
function render(){const r=route();const[k,id,round]=r.parts;const isOverview=!k||['sections','section','tournaments','tournament','edition'].includes(k);Object.entries({navHome:isOverview,navAll:['library','search','resource','business'].includes(k),navMine:k==='mine',navSaved:k==='saved'}).forEach(([n,on])=>{const el=$(n);el.classList.toggle('active',on);if(on)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});$('savedCount').textContent=saved.size?`(${saved.size})`:'';let html;if(!k||k==='sections')html=home();else if(k==='tournaments')html=home(true);else if(['library','search','mine','saved'].includes(k))html=pageList(k,r.params);else if(k==='section'&&SECTIONS.includes(id))html=sectionPage(id,r.params);else if(['tournament','edition'].includes(k)&&[...TOURNAMENTS,'共通'].includes(id))html=tournamentPage(id,r.params,k==='edition'?round||'':'');else if(k==='business'&&business(id))html=businessPage(business(id),r.params);else if(k==='resource'&&byId(id))html=detail(byId(id));else if(k==='news'&&id)html=newsPage(id);else if(k==='news'){crumb([['AIニュース']]);html=heading('AIニュース','外部のAI関連情報を受け取る表示例です。')+`<div class="news-list">${NEWS.map(n=>a('/news/'+n.id,`<div class="date">${n.date} · 架空記事／表示例</div><h2>${esc(n.headline)}</h2><p>${esc(n.body[0])}</p>`,'news-item')).join('')}</div>`;}else if(k==='codex')html=codexPage();else if(k==='slack')html=slackPage();else html=missing();$('page').innerHTML=html;$('quickSearch').value=k==='search'?r.params.get('q')||'':'';document.title=($('page').querySelector('h1')?.textContent||'業務ポータル')+'｜業務ポータル・案C';}
function setMode(m){mode=m;document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===m));$('urlField').hidden=m!=='link';$('fileField').hidden=m!=='html';$('rUrl').disabled=m!=='link';$('rUrl').required=m==='link';$('rFile').disabled=m!=='html';$('rFile').required=m==='html';$('rType').disabled=m==='html';}
function updateBusinesses(){const bs=BUSINESSES.filter(b=>b.section===$('rSection').value);$('rBusiness').innerHTML='<option value="">指定しない</option>'+bs.map(b=>`<option value="${b.id}">${esc(b.title)}</option>`).join('');}
function updateRecipients(){const limited=$('rShare').value==='指定アカウントのみ';$('recipientField').hidden=!limited;$('rRecipients').required=limited;}
function openRegister(){$('registerDialog').showModal();}
document.addEventListener('click',e=>{const btn=e.target.closest('button');if(btn?.hasAttribute('data-close'))btn.closest('dialog')?.close();if(btn?.dataset.mode)setMode(btn.dataset.mode);if(btn?.dataset.save){const id=Number(btn.dataset.save);if(!byId(id))return;const added=!saved.has(id);added?saved.add(id):saved.delete(id);persist();render();toast(added?'保存済みに追加しました。':'保存済みから外しました。');}if(btn?.dataset.external)openExternal(byId(btn.dataset.external));if(btn?.dataset.request)showSlack(byId(btn.dataset.request));if(btn?.dataset.requestDemo){const m=byId(btn.dataset.requestDemo);info('申請後の表示例',`<div class="notice">デモ表示です。Slackへは送信していません。</div><div class="step"><strong>アクセス申請を受け付けました（表示例）</strong>資料：${esc(m.title)}<br>公開者の確認後、GitHubへの招待を受け取る想定です。</div><div class="modal-actions"><button class="btn primary" data-close>閉じる</button></div>`);}if(btn?.hasAttribute('data-register'))openRegister();if(btn?.hasAttribute('data-picks')){pickOffset+=2;$('pickLines').innerHTML=picks();}if(e.target.closest('a[href^="#/"]'))document.querySelectorAll('dialog[open]').forEach(d=>d.close());});
$('searchForm').onsubmit=e=>{e.preventDefault();go('/search?q='+encoded($('quickSearch').value.trim()));};
$('page').addEventListener('change',e=>{const f=e.target.closest('#filters');if(!f)return;const r=route();for(const name of ['section','tournament','type','round','sort']){const el=f.elements[name];if(!el)continue;el.value?r.params.set(name,el.value):r.params.delete(name);}if(e.target.name==='tournament')r.params.delete('round');go('/'+r.parts.map(encoded).join('/')+(r.params.size?'?'+r.params.toString():''));});
$('accountButton').onclick=()=>info('Googleアカウントでログイン','<p class="lead">正式版では会社のGoogleアカウントでログインする想定です。</p><div class="notice">現在はサンプルユーザーとして表示しています。実際の認証は行いません。</div>');
$('openRegister').onclick=openRegister;
$('rSection').innerHTML=SECTIONS.map(s=>`<option>${s}</option>`).join('');$('rSection').value='カスタマー';$('rTournament').innerHTML=[...TOURNAMENTS,'共通'].map(t=>`<option>${t}</option>`).join('');$('rTournament').value='共通';updateBusinesses();$('rSection').onchange=updateBusinesses;$('rShare').onchange=updateRecipients;setMode('link');
$('registerForm').addEventListener('input',e=>e.target.setCustomValidity?.(''));
$('registerForm').onsubmit=e=>{e.preventDefault();const f=e.target;if(!f.reportValidity())return;const title=$('rTitle').value.trim();if(!title){$('rTitle').setCustomValidity('タイトルを入力してください');$('rTitle').reportValidity();return;}let url='';if(mode==='link'){try{const u=new URL($('rUrl').value.trim());if(!['http:','https:'].includes(u.protocol))throw Error();url=u.href;}catch{$('rUrl').setCustomValidity('http:// または https:// のURLを入力してください');$('rUrl').reportValidity();return;}}if(mode==='html'&&!/\.html?$/i.test($('rFile').files[0]?.name||'')){toast('HTMLファイルを選んでください');return;}const filename=mode==='html'?$('rFile').files[0].name:'';const id=Math.max(1000,...MATERIALS.map(m=>m.id))+1;MATERIALS.unshift({id,title,business:$('rBusiness').value,section:$('rSection').value,tournament:$('rTournament').value,round:$('rRound').value.trim(),tag:$('rTag').value.trim(),purpose:$('rPurpose').value.trim(),type:mode==='html'?'HTML':$('rType').value,link:mode==='html'?'HTML資料（未アップロード）':url,url,filename,share:$('rShare').value,recipients:$('rShare').value==='指定アカウントのみ'?$('rRecipients').value:'',owner:'sha',updated:new Intl.DateTimeFormat('ja-JP',{timeZone:'Asia/Tokyo',month:'long',day:'numeric'}).format(new Date())});persist();f.reset();$('rSection').value='カスタマー';$('rTournament').value='共通';updateBusinesses();updateRecipients();setMode('link');$('registerDialog').close();go('/resource/'+id);toast('デモ内に登録しました。実際の保存・送信は行っていません。');};
window.addEventListener('hashchange',()=>{document.querySelectorAll('dialog[open]').forEach(d=>d.close());render();window.scrollTo(0,0);});render();
